// Welche Dokumente qualifizieren?
//  - Webhook aus dem Paperless-Workflow „Dokument hinzugefügt“: die ID aus doc_url (…/documents/123/details) oder dokument_id
//  - Zeitplan oder manueller Start: offene Dokumente (DOKID leer) suchen – Auffangnetz, falls ein Aufruf verloren ging
const cfg = $('Konfiguration').first().json;
const b = typeof cfg.body === 'object' && cfg.body ? cfg.body : {};
const q = typeof cfg.query === 'object' && cfg.query ? cfg.query : {};
const erneut = [b.erneut, q.erneut].some((x) => x === true || x === 'true' || x === '1');
for (const roh of [b.dokument_id, b.doc_id, b.id, q.dokument_id, b.doc_url, b.url]) {
  if (roh == null || roh === '') continue;
  const t = String(roh).trim();
  const m = /documents\/(\d+)/.exec(t) || /^(\d+)$/.exec(t);
  if (m) return [{ json: { id: Number(m[1]), erneut } }];
}
return [{ json: { suchen: true } }];

// Dokument einordnen und entscheiden, ob es qualifiziert wird (Modus: je Element)
const doc = $input.item.json;
if (doc.error || !doc.id) return { json: { weiter: false, grund: `Dokument nicht lesbar: ${doc.error?.message ?? doc.error ?? 'unbekannt'}` } };
const liste = (j) => (Array.isArray(j) ? j : j.results ?? []);
const felder = liste($('Custom Fields laden').first().json);
const typen = liste($('Dokumenttypen laden').first().json);
const feld = (name) => felder.find((f) => String(f.name).trim().toLowerCase() === name.toLowerCase()) ?? null;
const dokid = feld('DOKID');
const cf = Array.isArray(doc.custom_fields) ? doc.custom_fields : [];
const schonQualifiziert = !!dokid && cf.some((x) => x.field === dokid.id && x.value !== null && x.value !== '');
const erneut = $('Je Dokument').item.json.erneut === true;
if (schonQualifiziert && !erneut) return { json: { weiter: false, grund: 'bereits qualifiziert (DOKID gesetzt)' } };

// Art des Dokuments: Halle/Jugend über den Dokumenttyp, Getränke über den Inhalt
const typName = doc.document_type ? (typen.find((t) => t.id === doc.document_type)?.name ?? '') : '';
let art = 'standard';
if (typName === 'Hallenrechnung') art = 'halle';
else if (typName === 'Abrechnung Jugendtraining') art = 'jugend';
else if (/getränke[\s-]*knapp|getränkebox|getränke[\s-]*(?:&|und)[\s-]*freizeitservice/i.test(`${doc.content ?? ''} ${doc.title ?? ''}`)) art = 'getraenke';
return { json: { weiter: true, id: doc.id, art, typName } };

// Anfrage an OpenAI: das Dokument selbst (PDF als Datei, Bilder als Bild) – die Texterkennung von Paperless nur als Hinweis
const cfg = $('Konfiguration').first().json;
const doc = $('Dokument laden').item.json;
const v = $('Vorprüfung').item.json;
const liste = (j) => (Array.isArray(j) ? j : j.results ?? []);
const korr = liste($('Korrespondenten laden').first().json).map((c) => `${c.id}: ${c.name}`).join('\n');

const teile = [];
let datei = '';
const bin = $input.item.binary?.data;
if (bin) {
  const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
  const mime = (bin.mimeType || '').toLowerCase();
  const name = bin.fileName || doc.original_file_name || `dokument-${doc.id}`;
  if (buf.length > 20 * 1024 * 1024) datei = 'Datei größer als 20 MB – nur Texterkennung.';
  else if (mime === 'application/pdf' || /\.pdf$/i.test(name)) {
    teile.push({ type: 'file', file: { filename: /\.pdf$/i.test(name) ? name : `${name}.pdf`, file_data: `data:application/pdf;base64,${buf.toString('base64')}` } });
  } else if (/^image\/(png|jpe?g|gif|webp)$/.test(mime)) {
    teile.push({ type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}`, detail: 'high' } });
  } else datei = `Dateityp ${mime || 'unbekannt'} wird nicht übergeben – nur Texterkennung.`;
} else datei = 'Datei nicht geladen – nur Texterkennung.';

const auftrag = {
  standard: `1. Titel: kurz und aussagekräftig auf Deutsch (max. 80 Zeichen), z. B. "Rechnung Strom Januar 2026".
   Ausgangsrechnungen des Vereins mit einer Nummer im Format JJJJ_NNN (z. B. 2026_067): Titel "<Rechnungsnummer>_<Nachname> <Vorname>" des Rechnungsempfängers.
2. korrespondent_id: NUR aus der Liste unten; passt keiner eindeutig, null. Nichts erfinden.
3. ausstellungsdatum (Rechnungs- oder Briefdatum) als JJJJ-MM-TT, betrag = Gesamtbetrag brutto (oder Gutschriftsbetrag), belegnummer.
4. positionen: leere Liste.`,
  getraenke: `Getränkerechnung. Titel und Korrespondent werden nicht geändert (titel und korrespondent_id = null).
Lies ausstellungsdatum, betrag (brutto), netto, mwst, belegnummer (Auftrags- bzw. Rechnungsnummer) und ALLE positionen:
menge, text, preis (Einzelpreis), gesamt. Pfand- und Leergutrückgaben als eigene Position mit negativem Betrag.`,
  halle: 'Hallenrechnung. Titel und Korrespondent werden nicht geändert (titel und korrespondent_id = null). Nur ausstellungsdatum, betrag (brutto) und belegnummer; positionen leer.',
  jugend: 'Abrechnung Jugendtraining. Titel und Korrespondent werden nicht geändert (titel und korrespondent_id = null). Nur ausstellungsdatum, betrag (brutto) und belegnummer; positionen leer.',
}[v.art];

teile.unshift({ type: 'text', text: `Analysiere das beigefügte Dokument (gescannt oder fotografiert – lies es aus dem Bild, nicht nur aus dem Text).
${auftrag}
Unbekannte Werte: null. Beträge als Zahl mit Punkt (123.45).

VERFÜGBARE KORRESPONDENTEN (ID: Name):
${korr}

AKTUELLER TITEL: ${doc.title ?? ''}
${datei ? `HINWEIS: ${datei}\n` : ''}TEXTERKENNUNG VON PAPERLESS (kann fehlerhaft sein):
${String(doc.content ?? '').slice(0, 4000)}` });

const zahl = { type: ['number', 'null'] };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['titel', 'korrespondent_id', 'ausstellungsdatum', 'betrag', 'netto', 'mwst', 'belegnummer', 'positionen'],
  properties: {
    titel: { type: ['string', 'null'] }, korrespondent_id: { type: ['integer', 'null'] }, ausstellungsdatum: { type: ['string', 'null'] },
    betrag: zahl, netto: zahl, mwst: zahl, belegnummer: { type: ['string', 'null'] },
    positionen: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['menge', 'text', 'preis', 'gesamt'],
      properties: { menge: zahl, text: { type: 'string' }, preis: zahl, gesamt: zahl } } },
  },
};
return { json: { anfrage: {
  model: cfg.MODELL || 'gpt-4o',
  temperature: 0,
  messages: [
    { role: 'system', content: 'Du bist ein präziser Dokumenten-Analyst für Paperless-ngx eines Tennisvereins. Antworte ausschließlich im vorgegebenen JSON-Schema.' },
    { role: 'user', content: teile },
  ],
  response_format: { type: 'json_schema', json_schema: { name: 'dokument', strict: true, schema } },
} } };

// Ergebnis in ein PATCH für Paperless übersetzen: nur leere Felder füllen, Vorgaben aus dem Portal bleiben stehen
const doc = $('Dokument laden').item.json;
const v = $('Vorprüfung').item.json;
const antwort = $input.item.json;
const liste = (j) => (Array.isArray(j) ? j : j.results ?? []);
const felder = liste($('Custom Fields laden').first().json);
const korr = liste($('Korrespondenten laden').first().json);
const feld = (name) => felder.find((f) => String(f.name).trim().toLowerCase() === name.toLowerCase()) ?? null;

let ki;
try {
  if (antwort.error) throw new Error(antwort.error.message ?? JSON.stringify(antwort.error));
  const msg = antwort.choices?.[0]?.message;
  if (msg?.refusal) throw new Error(`abgelehnt: ${msg.refusal}`);
  ki = JSON.parse(msg?.content ?? '');
} catch (e) {
  // ohne DOKID: der nächste Lauf nach Zeitplan versucht es erneut
  return { json: { aendern: false, id: doc.id, grund: `Analyse fehlgeschlagen: ${e.message}` } };
}

const cf = new Map((Array.isArray(doc.custom_fields) ? doc.custom_fields : []).map((x) => [x.field, x.value]));
const leer = (f) => !!f && (!cf.has(f.id) || cf.get(f.id) === null || cf.get(f.id) === '');
const gesetzt = [];
const setze = (name, wert, immer = false) => {
  const f = feld(name);
  if (!f || wert === null || wert === undefined || (!immer && !leer(f))) return;
  cf.set(f.id, wert);
  gesetzt.push(name);
};

const zahl = (x) => (typeof x === 'number' && Number.isFinite(x) ? Math.round(x * 100) / 100 : null);
if (/^\d{4}-\d{2}-\d{2}$/.test(ki.ausstellungsdatum ?? '')) setze('Ausstellungsdatum', ki.ausstellungsdatum);
const betrag = zahl(ki.betrag);
if (betrag !== null) {
  const f = feld('Betrag');
  setze('Betrag', f?.data_type === 'monetary' ? `EUR${betrag.toFixed(2)}` : String(betrag));
}
if (v.art === 'getraenke' && ki.positionen?.length) {
  setze('JSON', JSON.stringify({
    auftragsnummer: ki.belegnummer ?? '', datum: ki.ausstellungsdatum, netto: zahl(ki.netto), mwst: zahl(ki.mwst), brutto: betrag,
    positionen: ki.positionen.map((p, i) => ({ pos: i + 1, menge: p.menge, text: p.text, preis: zahl(p.preis), gesamt: zahl(p.gesamt) })),
  }));
}
setze('DOKID', doc.id, true);

const patch = { custom_fields: [...cf].map(([field, value]) => ({ field, value })) };
if (v.art === 'standard') {
  // Titel nur ersetzen, wenn er noch dem Dateinamen entspricht (also keine Regel ihn vorgegeben hat)
  const stamm = String(doc.original_file_name ?? '').replace(/\.[^.]+$/, '');
  if (ki.titel && (!doc.title || doc.title === stamm)) { patch.title = String(ki.titel).slice(0, 128); gesetzt.push('Titel'); }
  if (!doc.correspondent && ki.korrespondent_id && korr.some((c) => c.id === ki.korrespondent_id)) { patch.correspondent = ki.korrespondent_id; gesetzt.push('Korrespondent'); }
}
return { json: { aendern: true, id: doc.id, patch, gesetzt: gesetzt.join(', ') } };
